function TrailTaskCellNode:Awake()
    self.container = self.controller.transform:Find("Container")
    SetButtonAction(self.Button, function()
        if checkNumber(self.dojo.status) == 1 then
            --已完成 领取奖励
            GameUtils.Request(Interfaces.TrialTaskDraw, { id = checkString(self.taskVo.taskId) }, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = checkTable(response.data)
                    if data and isSet(data, "rewards") and table.count(data.rewards) > 0 then
                        GoodsUtils.DrawRewards(data.rewards)
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards } })
                    end
                    --刷新界面
                    self.clickCallBack()
                end
            end)
        else
            ---未完成的情况下
            ---未完成的任务如果配表前往的逻辑
            if self.taskVo.openType and checkNumber(self.taskVo.openType) > 0 then
                local goodsConfMgr = GoodsConfMgr:GetInstance()
                ---@type TableML.TableFileRow
                local row = goodsConfMgr:GetJumpModuleRow(self.taskVo.openType)
                goodsConfMgr:ExecuteJump(row, {})
            else
                GameUtils.Toast(localize('任务未完成'))
            end
        end
    end)
end

---FreshNode
---刷新任务格子信息
---@param taskVo TrailTaskVo 本地配表的任务信息数据
---@param dojo table 远程的进度数据
---@param callBack fun():void 点击回调
function TrailTaskCellNode:FreshNode(taskVo, dojo, callBack)
    self.taskVo = taskVo
    self.dojo = dojo
    if not isNull(callBack) then
        self.clickCallBack = callBack
    end

    self.NameTxt.text = checkString(taskVo.taskDescription)
    --self.TitleTxt.text = string.format_color_tag(tostring(math.floor(checkNumber(dojo.progress))), '#e2237a') .. "/" .. taskVo.taskContent
    self.TitleTxt.text = string.format("<size=30><color=#545454>%s</color></size>/%s", dojo.progress, taskVo.taskContent)
    self.Slider.value = checkNumber(dojo.progress) / taskVo.taskContent
    local canGet = checkNumber(dojo.status) == Constants.GetStatus.Can
    CfUtils.SetUISwitchImage(self.Fill, canGet and SwitchImageStatus.Can or SwitchImageStatus.Other)
    CfUtils.SetUISwitchImage(self.ImgFrame1, canGet and SwitchImageStatus.Can or SwitchImageStatus.Other)
    CfUtils.SetUISwitchImage(self.ImgFrame2, canGet and SwitchImageStatus.Can or SwitchImageStatus.Other)

    if not isNull(dojo) then
        --   printInfo(table.dump(dojo))
        if checkNumber(dojo.status) == 2 then
            --已领取
            KTool.SetActive(self.HasDrawnNode.gameObject, true)
            KTool.SetActive(self.ProgressNode.gameObject, false)
        else
            if checkNumber(dojo.status) == 1 then
                KTool.SetActive(self.Button.gameObject, true)
                KTool.SetActive(self.TaskingText.gameObject, false)
                self.Button.gameObject:GetComponent("FontStyleButton"):ResetFontStyle("B12", localize("领取"))
                --KTool.SetActive(self.ProgressBarText.gameObject, false)
            else
                ---未完成的任务如果配表前往的逻辑
                if checkInt(taskVo.openType) > 0  then
                    KTool.SetActive(self.Button.gameObject, true)
                    KTool.SetActive(self.TaskingText.gameObject, false)
                    self.Button.gameObject:GetComponent("FontStyleButton"):ResetFontStyle("B13", localize("前往"))
                    --KTool.SetActive(self.ProgressBarText.gameObject, true)
                else
                    KTool.SetActive(self.Button.gameObject, false)
                    KTool.SetActive(self.TaskingText.gameObject, true)
                    local textComp = KTool.GetComponent(self.TaskingText.gameObject, typeof(Text))
                    textComp.text = localize('进行中')
                    --KTool.SetActive(self.ProgressBarText.gameObject, true)
                end
            end
            --未领取
            KTool.SetActive(self.HasDrawnNode.gameObject, false)
            KTool.SetActive(self.ProgressNode.gameObject, true)
            --self.ProgressBarText:GetComponent(typeof(TextMeshProUGUI)).text = string.format_color_tag(tostring(math.floor(checkNumber(dojo.progress))), '#e2237a') .. "/" .. taskVo.taskContent
        end
    else
        KTool.SetActive(self.HasDrawnNode.gameObject, false)
        KTool.SetActive(self.ProgressNode.gameObject, true)
        --self.ProgressBarText:GetComponent(typeof(TextMeshProUGUI)).text = "0/" .. taskVo.taskContent
        KTool.SetActive(self.controller.gameObject, false)
    end

    local parentGo = self.RewardsNode.gameObject
    KTool.DestroyGameObjectChildren(parentGo)
    ---生成prefab的奖励格子
    local rewards = clone(taskVo.rewards)
    if #rewards > 0 then
        local PrefabGo = self.RewardGoodNode.gameObject
        for _, v in pairs(rewards) do
            ---@type UnityEngine.GameObject
            local go = parentGo:AddChild(PrefabGo)
            KTool.SetActive(go, true)
            local goodNodeGo = go.transform:Find("GoodNode")
            local goodNodeMB = GetLuaBehaviour(goodNodeGo.gameObject, GoodNodeMBPath)
            if KTool.IsNull(goodNodeMB.Env) then
                goodNodeMB:Init()
            end
            if not KTool.IsNull(goodNodeMB) then
                ---@type GoodNodeMB
                local env = goodNodeMB.Env
                env:SetClickButtonAction(function(goodsId)
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                    if isTable(vo) then
                        GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
                    end
                end)
                env:Reload({ goodsId = v.goodsId,
                             isShowNo = true, text = 'x' .. FormatCurrencyNum(v.goodsNum)
                })
            end
        end
    end
end
function TrailTaskCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TrailTaskCellNode